import{z as A,x as B,o as r,c as p,q as t,j as s,D as E,d as l,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"滚动发布","description":"","frontmatter":{"title":"滚动发布","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-rolling-release.md","filePath":"cs/orch-rolling-release.md","lastUpdated":1791063341000}'),d={name:"cs/orch-rolling-release.md"};function c(D,e,m,S,g,h){const o=B("Mermaid");return r(),p("div",null,[e[2]||(e[2]=t('<h1 id="滚动发布" tabindex="-1">滚动发布 <a class="header-anchor" href="#滚动发布" aria-label="Permalink to &quot;滚动发布&quot;">​</a></h1><div class="epigraph"><p>发布不是把新版本放上去，是让旧版本体面地退场；大多数发布事故死在后一半。</p><footer>—— 据 Kubernetes 官方文档（Deployments）与 Google SRE 书（Beyer et al., 2016）发布实践整理</footer></div><p><a href="/cs/orch-service-discovery">上一课</a>留下一根命脉：readiness 决定端点进不进池，端点集合随调和收敛。滚动发布正是把这根线用满的控制器：Deployment 用两个版本的 ReplicaSet，把「换版本」写成两个速率受控的扩缩容。主干课 <a href="/cs/rolling-upgrade">滚动升级</a> 给过轮廓；本课深钻三件事：容量预算的公式、探针的门控、以及旧 pod 的退场合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全量替换的问题是失败半径：新版本全错时没有退路，用户全量承担。朴素的逐个替换的问题是容量：新旧交替时服务能力忽高忽低，谁也没说清任意时刻最少还有几个 pod 在接流量。缺口是把切换写成有公式的受控过程：任意时刻的容量下界、失败半径上界、以及「什么算可以接流量」的判据，都要事先钉死，而不是发布当晚临时解释。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Deployment 到 ReplicaSet 到 Pod，一版一个 ReplicaSet，留痕即历史。两个预算参数：<strong>maxSurge</strong> 管最多多出几个新 pod（容量上界），<strong>maxUnavailable</strong> 管最多少几个旧 pod（容量下界），默认各为副本数的四分之一上下。设副本数为 \\(n\\)，则任意时刻可用容量满足 \\(n_{\\text{avail}} \\ge n - \\lfloor u \\cdot n \\rfloor\\)，单轮失败半径 \\(\\le \\lceil s \\cdot n \\rceil\\)，其中 \\(u\\)、\\(s\\) 是两个预算。新 pod 过 readiness 才计入可用；旧的在缩掉前从端点池摘除。暂停与恢复支持中途观察；回滚就是「把旧 ReplicaSet 的副本数调回去」——又是调和，不是专用机制。</p><p><span class="marginnote">数字实例：副本数 \\(n=10\\)、maxSurge=2、maxUnavailable=1 时，任意时刻 pod 总数在 9 到 12 之间——先多开 2 个新 pod，每就绪 1 个才缩 1 个旧的；就算新版本一个都起不来，服务也始终至少有 9 个旧 pod 在接流量，这就是容量下界的含义。</span></p>',8)),(r(),s(n,null,{default:E(()=>[i(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22Deployment%20spec%20%E6%8D%A2%E9%95%9C%E5%83%8F%22%5D%20--%3E%20NEW%5B%22%E6%96%B0%20ReplicaSet%20%E6%89%A9%E5%AE%B9%22%5D%0A%20%20NEW%20--%3E%20RDY%7B%22%E6%96%B0%20pod%20%E8%BF%87%20readiness%3F%22%7D%0A%20%20RDY%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%5B%22%E4%B8%8D%E8%BF%9B%E6%B1%A0%2C%20%E4%B8%8D%E8%AE%A1%E5%85%A5%E5%8F%AF%E7%94%A8%22%5D%0A%20%20RDY%20--%3E%7C%22%E6%98%AF%22%7C%20OLD%5B%22%E6%97%A7%20ReplicaSet%20%E7%BC%A9%E5%AE%B9%22%5D%0A%20%20OLD%20--%3E%20EP%5B%22%E7%AB%AF%E7%82%B9%E6%91%98%E9%99%A4%E4%B8%8E%E4%BC%A0%E6%92%AD%22%5D%0A%20%20EP%20--%3E%20TERM%5B%22SIGTERM%3A%20%E4%BC%98%E9%9B%85%E9%80%80%E5%9C%BA%22%5D%0A%20%20TERM%20--%3E%20GONE%5B%22grace%20%E6%9C%9F%E6%BB%A1%E5%BC%BA%E6%9D%80%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"readiness 的门控把「进程活着」与「能接流量」解耦：缓存未预热、连接池未建好、依赖未就绪，都发生在进程已启动之后；没有门控，新 pod 一启动就进池，用户替它的冷启动买单。退场是事故最密集的一段，合同有固定顺序：先发 SIGTERM 并执行 preStop 钩子——此刻 pod 还在池上，睡一小段等转发规则把摘除传播出去；随后端点摘除；grace 期内处理存量请求；期满强杀。两个经典错法都在顺序上：先摘端点再立刻退出，砍掉全部在途请求；依赖进程收到 SIGTERM 就瞬间退出，连接池里的请求一起陪葬。把退场当成和扩容同等重要的半边，发布的可靠性才闭合。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：readiness 探针就是店铺的「营业中」牌子——进程启动只代表店门开了（liveness 管的是「死了没」），货架摆没摆好是另一回事；牌子不翻（未就绪），排号机（端点池）就不会把客人（流量）分过来。")],-1)),(r(),s(n,null,{default:E(()=>[i(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCALE%5B%22%E6%97%A7%20ReplicaSet%20%E7%BC%A9%E6%8E%89%201%20%E4%B8%AA%22%5D%20--%3E%20SIG%5B%22%E5%8F%91%20SIGTERM%20%E5%B9%B6%E6%89%A7%E8%A1%8C%20preStop%22%5D%0A%20%20SIG%20--%3E%20SLEEP%5B%22pod%20%E4%BB%8D%E5%9C%A8%E6%B1%A0%E4%B8%8A%2C%20%E7%9D%A1%E5%87%A0%E7%A7%92%E7%AD%89%E8%BD%AC%E5%8F%91%E8%A7%84%E5%88%99%E4%BC%A0%E6%92%AD%22%5D%0A%20%20SLEEP%20--%3E%20EP%5B%22%E4%BB%8E%E7%AB%AF%E7%82%B9%E6%B1%A0%E6%91%98%E9%99%A4%22%5D%0A%20%20EP%20--%3E%20DRAIN%5B%22grace%20%E6%9C%9F%E5%86%85%E7%BB%A7%E7%BB%AD%E5%A4%84%E7%90%86%E5%AD%98%E9%87%8F%E8%AF%B7%E6%B1%82%22%5D%0A%20%20DRAIN%20--%3E%20KILL%5B%22grace%20%E6%9C%9F%E6%BB%A1%E5%BC%BA%E6%9D%80%22%5D%0A%20%20DRAIN%20--%3E%7C%22%E6%94%B6%E5%B0%BE%E8%B6%85%E8%BF%87%20grace%20%E6%9C%9F%22%7C%20FORCE%5B%22%E8%A2%AB%E5%BC%BA%E6%9D%80%2C%20%E5%9C%A8%E9%80%94%E8%AF%B7%E6%B1%82%E6%8A%A5%E9%94%99%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t('<p>自动回滚需要外部判据：控制器自己不知道新版本是好是坏，错误预算的烧速是现成的裁判——见 <a href="/cs/obs-slo-engineering">SLO 工程</a>。若新版本放大了对下游的失败，发布期间还要配上 <a href="/cs/rate-limit-circuit-breaker">限流与熔断</a> 的既有防线，而不是指望预算参数挡住逻辑错误。</p><p><span class="marginnote">数字：优雅退场的默认预算是 30 秒——比这长的收尾必须显式改 terminationGracePeriodSeconds，否则每次发布都在制造一批被强杀的在途请求，而表象只是「错误率偶尔抖一下」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>回滚即时的是数据面：schema 与数据不回滚，不兼容变更要走「先扩张后收缩」的双阶段，那是数据工程的合同。节点维护时的驱逐预算（PDB）与发布预算是两回事，前者管「一次意外最多拿走几个」，后者管「主动换版本的速度」。批量发布的灰度比例、按地域分批，是 Deployment 之上的编排，本课不展开。</p><p><span class="marginnote">常见误区：初学者容易把发布预算（maxSurge/maxUnavailable）与驱逐预算（PDB）当成一回事。前者管「主动换版本时最多拿走几个」，后者管「节点宕机等意外最多拿走几个」；把发布安全寄托在 PDB 上、或反过来，都会在事故当晚发现两本账对不上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发布是速率受控的双向扩缩容：maxSurge 定容量上界，maxUnavailable 定下界。</li><li>readiness 门控把「活着」与「能接」解耦，冷启动的代价不该由用户付。</li><li>退场合同有顺序：preStop 等传播、摘端点、grace 内处理存量、期满强杀。</li><li>回滚是调旧 ReplicaSet 的副本数；好坏要外部判据，控制器自己不判断。</li><li>出处：Kubernetes 官方文档（Deployments）；Google SRE 书（Beyer et al., 2016）。</li></ul>',7))])}const f=A(d,[["render",c]]);export{u as __pageData,f as default};
